import os
import re
from typing import Any, Dict, List, Optional, Tuple

import requests


PERSPECTIVE_API_URL = "https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze"


def _sentence_spans(text: str) -> List[Tuple[int, int]]:
    spans: List[Tuple[int, int]] = []
    start = 0
    for match in re.finditer(r"[^.!?]+[.!?]?\s*", text, flags=re.DOTALL):
        s, e = match.span()
        if s == e:
            continue
        spans.append((s, e))
        start = e
    if not spans and text:
        spans.append((0, len(text)))
    elif spans and spans[-1][1] < len(text):
        spans.append((spans[-1][1], len(text)))
    return [(s, e) for s, e in spans if s < e]


def _clamp01(value: Any) -> float:
    try:
        v = float(value)
    except (TypeError, ValueError):
        return 0.0
    if v < 0.0:
        return 0.0
    if v > 1.0:
        return 1.0
    return v


def _merge_spans(spans: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
    if not spans:
        return []
    spans = sorted(spans)
    merged = [spans[0]]
    for s, e in spans[1:]:
        ls, le = merged[-1]
        if s <= le:
            merged[-1] = (ls, max(le, e))
        else:
            merged.append((s, e))
    return merged


def _redact_text(text: str, spans: List[Tuple[int, int]], mask: str = "[REDACTED]") -> str:
    if not spans:
        return text
    spans = _merge_spans([(max(0, s), min(len(text), e)) for s, e in spans if s < e])
    out = []
    last = 0
    for s, e in spans:
        if s > last:
            out.append(text[last:s])
        out.append(mask)
        last = e
    if last < len(text):
        out.append(text[last:])
    return "".join(out)


def _analyze_with_perspective(text: str, api_key: str, attributes: Optional[List[str]] = None) -> Dict[str, Any]:
    if attributes is None:
        attributes = ["TOXICITY", "SEVERE_TOXICITY", "INSULT", "THREAT", "IDENTITY_ATTACK", "PROFANITY"]
    payload = {
        "comment": {"text": text},
        "requestedAttributes": {attr: {} for attr in attributes},
        "doNotStore": True,
        "languages": ["en"],
    }
    params = {"key": api_key}
    resp = requests.post(PERSPECTIVE_API_URL, params=params, json=payload, timeout=30)
    resp.raise_for_status()
    return resp.json()


def _parse_scores(response: Dict[str, Any]) -> Dict[str, float]:
    scores: Dict[str, float] = {}
    attrs = response.get("attributeScores", {}) or {}
    for name, data in attrs.items():
        try:
            scores[name] = _clamp01(data["summaryScore"]["value"])
        except Exception:
            scores[name] = 0.0
    return scores


def _find_unsafe_spans(text: str, scores: Dict[str, float], threshold: float) -> List[Tuple[int, int]]:
    if not scores:
        return []
    max_score = max(scores.values())
    if max_score < threshold:
        return []
    spans = _sentence_spans(text)
    if len(spans) == 1:
        return spans
    unsafe: List[Tuple[int, int]] = []
    # Conservative heuristic: if any high-risk attribute exceeds threshold, redact the most
    # recent sentence-sized chunks by proportional score.
    risky_attrs = {"TOXICITY", "SEVERE_TOXICITY", "INSULT", "THREAT", "IDENTITY_ATTACK", "PROFANITY"}
    risk_score = max(scores.get(attr, 0.0) for attr in risky_attrs)
    if risk_score >= threshold:
        if risk_score >= min(0.95, threshold + 0.2):
            unsafe.extend(spans)
        else:
            unsafe.append(spans[-1])
    return _merge_spans(unsafe)


def flag_or_redact_unsafe_spans(
    text: str,
    *,
    mode: str = "redact",
    threshold: float = 0.70,
    api_key: Optional[str] = None,
    return_details: bool = False,
) -> Any:
    api_key = api_key or os.getenv("PERSPECTIVE_API_KEY")
    if not api_key:
        raise ValueError("Missing PERSPECTIVE_API_KEY")

    response = _analyze_with_perspective(text, api_key)
    scores = _parse_scores(response)
    unsafe_spans = _find_unsafe_spans(text, scores, threshold)

    result = {
        "unsafe": bool(unsafe_spans),
        "scores": scores,
        "spans": [{"start": s, "end": e, "text": text[s:e]} for s, e in unsafe_spans],
        "text": _redact_text(text, unsafe_spans) if mode == "redact" else text,
    }

    if mode not in {"redact", "flag"}:
        raise ValueError("mode must be 'redact' or 'flag'")

    if mode == "flag":
        result["text"] = text

    if return_details:
        return result
    return result["text"] if mode == "redact" else result["unsafe"]
